///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.TR_JOB;
scwin.vIsurCd, scwin.vIsurNm, scwin.vInputRnd, scwin.vTrJob, scwin.vAcptNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const sbmOptions = {
            id : "sbm_dts_Item",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Item=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Item.insertRow();
        // dts_File.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        file_name.hide();
        const parentWin = $c.frame.path("../");
        scwin.vIsurCd = parentWin.gIsurCd;
        scwin.vIsurNm = parentWin.gIsurNm;
        scwin.vInputRnd = parentWin.gInputRnd;
        scwin.vTrJob = parentWin.gGubnStat;
        scwin.vAcptNo = parentWin.gAcptNo;
        if (scwin.vTrJob === "U") {
            txb_ISUR_CD.setValue(scwin.vIsurCd);
            txb_COM_NM.setValue(scwin.vIsurNm);
            txb_ISUR_CD.setReadOnly(true);
            btn_lineadd.setBackgroundImage("../img/btn_fileadd_dis.gif");
            btn_lineadd.setDisabled(true);
            btn_linedelete.setBackgroundImage("../img/btn_filedelete_dis.gif");
            btn_linedelete.setDisabled(true);
            // btn_save.src = "../img/btn_save_d.gif";
            // btn_save.disabled = true;
            img_COM_NM.setBackgroundImage("../img/btn_search_d.gif");
            img_COM_NM.setDisabled(true);
            btn_save.setBackgroundImage("../img/btn_save_d.gif");
            btn_save.setDisabled(true);
            scwin.updateUI();
            await scwin.readSync();
        } else {
            btn_update.setBackgroundImage("../img/btn_modify_d.gif");
            btn_update.setDisabled(true);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05961.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

