/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (dts_File.getRowCount() === 5) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_File.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_File.removeRow(dts_File.getRowPosition());
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05961.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_File.removeRow(dts_File.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name grd_ATTACH_FILE_OnDblClick
 * @description grd_ATTACH_FILE 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_ATTACH_FILE_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_File.getRowStatus(dts_File.getRowPosition()) === 0) {
            scwin.filedown(dts_File);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.grd_ATTACH_FILE_OnDblClick" });
    }
};

