/**
 * @method
 * @name sectAhthQualCdSync
 * @description sect Ahth Qual Cd Sync 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sectAhthQualCdSync = async function(nIndex) {
    if (nIndex === "1") {
        if (cmb_SECT_AHTH_QUAL_TP_CD_1.getValue() === "1") {
            const sbmOptions = {
                id : "sbm_dts_SectAhthQualCd_1",
                action : "/CodeAction.do",
                ref : "",
                target : "dts_SectAhthQualCd_1=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            const sbmOptions2 = {
                id : "sbm_dts_SectAhthInstCd_1",
                action : "/CodeAction.do",
                ref : "",
                target : "dts_SectAhthInstCd_1=body.content",
                isProcessMsg : false
            };

            const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
            // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        } else {
            cmb_SECT_AHTH_QUAL_CD_1.setValue("");
            cmb_SECT_AHTH_INST_CD_1.setValue("");
        }
    } else if (nIndex === "2") {
