/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = scwin.vTrJob;
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        /*	if(vTrJob == "U"){
        		dts_Item.UserStatus(1) = TB_JOB_UPDATE;
        	} else {
        		dts_Item.UserStatus(1) = TB_JOB_INSERT;
        	}*/

        scwin.setValue();
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/SectionTypeChange.do",
            ref : "dts_Item,dts_File",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
         * @method
         * @name fileReadSync
         * @description file Read Sync 처리
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.fileReadSync = async function() {
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=SECT_TYP_CHG_CERT_ATTACHFILE_OUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.scttypchg.select.ahthqual.attachfile";
    url += "&{P}param01=" + scwin.vAcptNo;
    url += "&{P}param02=" + scwin.vIsurCd + $c.ut.lpad(scwin.vInputRnd, 9, "0");
    const sbmOptions = {
        id : "sbm_dts_File",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_File=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

