/**
 * @method
 * @name filedown
 * @description filedown 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(dtsObj) {
    const vBzProcsNo = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "BZ_PROCS_NO");
    const vDisclsDocNo = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "DISCLS_DOC_NO");
    const attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    if (vBzProcsNo !== '') location.href = "/filedownload.do?file_id=" + vBzProcsNo + "&attach_seq=" + attach_seq + "&gubun=23";

    else if (vDisclsDocNo !== '') location.href = "/filedownload.do?file_id=" + vDisclsDocNo + "&attach_seq=" + attach_seq + "&gubun=12";
};

